if set(SETUP_PRIVACY_CATALOGS) != EXPECTED_SETUP_PRIVACY_LOCALES:
    raise ValueError("Onboarding setup/privacy locale coverage is incomplete")

if any(
    set(entries) != set(SETUP_PRIVACY_KEYS)
    for entries in SETUP_PRIVACY_CATALOGS.values()
):
    raise ValueError(
        "Onboarding setup/privacy catalog source coverage is incomplete"
    )

if any(
    not value.strip() or value == key
    for entries in SETUP_PRIVACY_CATALOGS.values()
    for key, value in entries.items()
):
    raise ValueError(
        "Onboarding setup/privacy translations must be explicit non-English copy"
    )
